-- Migration: Preserve all time standards data
-- Created: 2026-01-27
-- Purpose: Preserve all existing time standards data from unified_time_standards and time_standard_types tables
-- This migration ensures all data is preserved for future use even if tables are recreated

-- Note: This migration should be run AFTER the tables are created
-- It preserves all data that currently exists in the database

-- ============================================================================
-- TIME STANDARD TYPES DATA
-- ============================================================================

-- Temporarily disable triggers and constraints for faster inserts
ALTER TABLE time_standard_types DISABLE TRIGGER ALL;
ALTER TABLE unified_time_standards DISABLE TRIGGER ALL;

-- Insert time_standard_types data
-- These IDs must match the existing IDs in the database to maintain referential integrity
ON CONFLICT (competition, standard_type) DO UPDATE SET
  description = EXCLUDED.description,
  updated_at = EXCLUDED.updated_at;

-- ============================================================================
-- UNIFIED TIME STANDARDS DATA
-- ============================================================================
-- Total records: 403
-- All unified time standards data preserved from the database
-- Using ON CONFLICT to handle duplicates gracefully




-- Re-enable triggers and constraints
ALTER TABLE time_standard_types ENABLE TRIGGER ALL;
ALTER TABLE unified_time_standards ENABLE TRIGGER ALL;

-- Reset sequence to ensure new inserts don't conflict
SELECT setval('time_standard_types_id_seq', (SELECT MAX(id) FROM time_standard_types));
SELECT setval('unified_time_standards_id_seq', (SELECT MAX(id) FROM unified_time_standards));
